// ============================================================
// Tc2_Utilities.stLibVersion_Tc2_Utilities 演示程序
// ============================================================
// 注意：项目须引用 Tc2_Utilities 与 Tc2_System
// 验证步骤：
//   1. 编译 + 登录
//   2. 在线监视 stMyVer 应显示 2.18.2
//   3. 在线监视 bOk 应为 TRUE
// ============================================================

stMyVer := stLibVersion_Tc2_Utilities;

bOk := F_CmpLibVersion(
    stLibVersion := stLibVersion_Tc2_Utilities,
    iMajor := 2, iMinor := 18, iBuild := 2, iRevision := 0,
    nCmpType := E_CmpLibVersion.GreaterOrEqual
);
